# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CAMPUS FACILITIES, SCHOOL CLUBS &amp; ACADEMIC ROUTINES</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">CAMPUS FACILITIES (OKUL BİRİMLERİ)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Science Lab: Doing experiments &amp; research</text>\n  <text x="42" y="120" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Library: Borrowing books &amp; studying quietly</text>\n  <text x="42" y="144" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Gymnasium / Sports Hall: Physical education</text>\n  <text x="42" y="168" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Canteen / Cafeteria: Having lunch &amp; snacks</text>\n  <text x="42" y="192" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Conference Hall: Attending seminars &amp; plays</text>\n  <text x="182" y="220" text-anchor="middle" font-size="10.5" fill="#1d4ed8">IT Room · Art Studio · Guidance Counselor\'s Office</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ACADEMIC COLLOCATIONS (KALIP İFADELER)</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• attend classes / join an extracurricular club</text>\n  <text x="377" y="120" font-size="11.5" font-weight="bold" fill="#14532d">• hand in / submit an assignment on time</text>\n  <text x="377" y="144" font-size="11.5" font-weight="bold" fill="#14532d">• take notes / revise for exams regularly</text>\n  <text x="377" y="168" font-size="11.5" font-weight="bold" fill="#14532d">• do a project / give a presentation</text>\n  <text x="377" y="192" font-size="11.5" font-weight="bold" fill="#14532d">• follow the timetable / keep up with lessons</text>\n  <text x="517" y="220" text-anchor="middle" font-size="10.5" fill="#15803d">Robotics Club · Debate Club · Drama &amp; Chess Club</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EXPRESSING RULES, OBLIGATIONS &amp; PERMISSION</text>\n  <rect x="25" y="45" width="205" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">OBLIGATION (ZORUNLULUK)</text>\n  <text x="38" y="96" font-size="11.5" font-weight="bold" fill="#713f12">• must + V₁ (İçsel / Kural):</text>\n  <text x="45" y="114" font-size="10.5" fill="#334155">&quot;You must listen to the</text>\n  <text x="45" y="129" font-size="10.5" fill="#334155">teacher carefully.&quot;</text>\n  <text x="38" y="156" font-size="11.5" font-weight="bold" fill="#713f12">• have to / has to + V₁:</text>\n  <text x="45" y="174" font-size="10.5" fill="#334155">&quot;Students have to wear</text>\n  <text x="45" y="189" font-size="10.5" fill="#334155">school uniforms.&quot;</text>\n  <text x="127" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">He/She/It → has to + V₁</text>\n  <rect x="247" y="45" width="205" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">PROHIBITION vs. NO NECESSITY</text>\n  <text x="260" y="96" font-size="11" font-weight="bold" fill="#7f1d1d">• mustn\'t / can\'t (YASAK!):</text>\n  <text x="267" y="114" font-size="10.5" fill="#334155">&quot;You mustn\'t make noise</text>\n  <text x="267" y="129" font-size="10.5" fill="#334155">in the school library.&quot;</text>\n  <text x="260" y="156" font-size="11" font-weight="bold" fill="#15803d">• don\'t / doesn\'t have to:</text>\n  <text x="267" y="174" font-size="10.5" fill="#334155">(Zorunluluk yok / Gerekmez)</text>\n  <text x="267" y="189" font-size="10.5" fill="#334155">&quot;We don\'t have to go to</text>\n  <text x="267" y="204" font-size="10.5" fill="#334155">school on Sundays.&quot;</text>\n  <rect x="470" y="45" width="205" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">PERMISSION &amp; ADVICE</text>\n  <text x="483" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• can / may (İzin / Olanak):</text>\n  <text x="490" y="114" font-size="10.5" fill="#334155">&quot;You can borrow three</text>\n  <text x="490" y="129" font-size="10.5" fill="#334155">books from the library.&quot;</text>\n  <text x="483" y="156" font-size="11.5" font-weight="bold" fill="#581c87">• should / shouldn\'t (Tavsiye):</text>\n  <text x="490" y="174" font-size="10.5" fill="#334155">&quot;You should review your</text>\n  <text x="490" y="189" font-size="10.5" fill="#334155">notes after class.&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 2 REVISION: TENSES, ADVERBS &amp; QUESTION WORDS</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">PRESENT SIMPLE vs. CONTINUOUS</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#7c2d12">• Present Simple (Routines &amp; Timetables):</text>\n  <text x="52" y="114" font-size="10.5" fill="#334155">I/You/We/They + V₁  |  He/She/It + V-s/es/ies</text>\n  <text x="52" y="130" font-size="10.5" fill="#475569">&quot;She usually studies in the library after school.&quot;</text>\n  <text x="42" y="156" font-size="11.5" font-weight="bold" fill="#7c2d12">• Present Continuous (Actions Happening Now):</text>\n  <text x="52" y="174" font-size="10.5" fill="#334155">am / is / are + V-ing  (now, right now, at the moment)</text>\n  <text x="52" y="190" font-size="10.5" fill="#475569">&quot;Look! They are doing an experiment in the lab now.&quot;</text>\n  <text x="182" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#c2410c">Non-progressive: know, understand, want, need, like</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ADVERBS &amp; WH- QUESTIONS</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• How often...? (Ne sıklıkla?):</text>\n  <text x="387" y="114" font-size="10.5" fill="#334155">always, usually, often, sometimes, rarely, never,</text>\n  <text x="387" y="130" font-size="10.5" fill="#334155">twice a week, every day</text>\n  <text x="377" y="156" font-size="11.5" font-weight="bold" fill="#1e3a8a">• How...? (Nasıl? — Adverbs of Manner):</text>\n  <text x="387" y="174" font-size="10.5" fill="#334155">carefully, quietly, fluently, well, fast, hard, late</text>\n  <text x="387" y="192" font-size="10.5" fill="#475569">&quot;He speaks English fluently and works hard.&quot;</text>\n  <text x="517" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Position: S + freq. adverb + V  |  S + be + freq. adverb</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
